var ladderLength = function(beginWord, endWord, wordList) {
    if (beginWord === endWord) return 1;

    const unused = new Set(wordList);
    if (!unused.has(endWord)) return 0;

    let front = new Set([beginWord]);
    let back = new Set([endWord]);
    unused.delete(beginWord);
    unused.delete(endWord);
    let steps = 1;

    while (front.size > 0) {
        if (front.size > back.size) {
            const tmp = front; front = back; back = tmp;
        }

        const nextFront = new Set();
        for (const word of front) {
            const letters = word.split('');
            for (let index = 0; index < letters.length; index++) {
                const original = letters[index];
                for (let code = 97; code <= 122; code++) {
                    const replacement = String.fromCharCode(code);
                    if (replacement === original) continue;
                    letters[index] = replacement;
                    const candidate = letters.join('');
                    if (back.has(candidate)) return steps + 1;
                    if (unused.has(candidate)) {
                        unused.delete(candidate);
                        nextFront.add(candidate);
                    }
                }
                letters[index] = original;
            }
        }

        front = nextFront;
        steps += 1;
    }

    return 0;
};

solution.python:
from typing import List

class Solution:
    def ladderLength(self, beginWord: str, endWord: str, wordList: List[str]) -> int:
        if beginWord == endWord:
            return 1

        unused = set(wordList)
        if endWord not in unused:
            return 0

        front = {beginWord}
        back = {endWord}
        unused.discard(beginWord)
        unused.discard(endWord)
        steps = 1

        while front:
            if len(front) > len(back):
                front, back = back, front

            next_front = set()
            for word in front:
                letters = list(word)
                for index, original in enumerate(letters):
                    for code in range(ord('a'), ord('z') + 1):
                        replacement = chr(code)
                        if replacement == original:
                            continue
                        letters[index] = replacement
                        candidate = ''.join(letters)
                        if candidate in back:
                            return steps + 1
                        if candidate in unused:
                            unused.remove(candidate)
                            next_front.add(candidate)
                    letters[index] = original

            front = next_front
            steps += 1

        return 0
